mapper.select:
SELECT stat_date, tenant_id, source, metric_code, page_code, app_version,
       event_count, success_count, failure_count, last_seen_at
  FROM batch.console_usage_daily
 WHERE tenant_id = #{tenantId}
   AND stat_date BETWEEN #{from} AND #{to}

   AND metric_code = #{metricCode}


   AND page_code = #{pageCode}

 ORDER BY stat_date, metric_code, page_code
